mutation Login($email: String!, $password: String!) {
  login(email: $email, password: $password) { token user { id name email } }
}

query Me {
  me { id name email createdAt }
}

mutation Ask($prompt: String!) {
  askAdvice(topic: general, prompt: $prompt) {
    id content source
    steps { tool summary count }
    flights { id airline flightNumber origin destination price source }
  }
}

